mkdir -p scratch && cat > scratch/preview.mjs <<'EOF'
// Scratch preview only: shell west + stairs as the real build lays them, then the P2 room's air unlocked (unset) so the
// room part can be checked without the shared build's lock. Output goes to scratch/, never to build.nbt.
import { Grid, runParts } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { DATA_VERSIONS } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/structure.mjs";
import { SITE_SIZE, SERVER_VERSION } from "../vocab/base.mjs";
import * as shellWest from "../parts/shell-west.mjs";
import * as stairs from "../parts/stairs.mjs";
import * as room17 from "../parts/room-17.mjs";
const [SX, SY, SZ] = SITE_SIZE;
const g = new Grid([SX, SY, SZ], { dataVersion: DATA_VERSIONS[SERVER_VERSION] });
g.fill([0, 0, 0], [SX - 1, 0, 2], "gravel");
g.fill([0, 0, 3], [SX - 1, 0, 4], "smooth_stone");
g.fill([0, 0, 5], [SX - 1, 0, SZ - 1], "grass_block");
runParts(g, [["shell west", shellWest.build], ["stairs", stairs.build, { carve: true }]], { palette: "../palette.json", report: null });
for (let x = 36; x <= 43; x++) for (let y = 2; y <= 4; y++) for (let z = 14; z <= 17; z++) g.unset(x, y, z);
room17.build(g);
g.save(process.argv[2]);
console.log("preview saved", g.refused.length, "refused");
EOF
node scratch/preview.mjs scratch/preview.nbt 2>&1 | tail -3; MCD="/Volumes/ext1/swe/repos/minecraft-design/tools/bin/mcd.mjs"; node $MCD room scratch/preview.nbt --rooms rooms.json --only "P2 living and dining" 2>&1 | head -60; date

